package com.example.minicommerce.messaging.application;
import com.example.minicommerce.messaging.config.RabbitTopology;import com.example.minicommerce.messaging.infrastructure.OutboxJdbcRepository;import com.example.minicommerce.shared.config.AppProperties;import io.micrometer.core.instrument.MeterRegistry;import java.nio.charset.StandardCharsets;import java.util.UUID;import java.util.concurrent.TimeUnit;import org.slf4j.*;import org.springframework.amqp.core.*;import org.springframework.amqp.rabbit.connection.CorrelationData;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component@ConditionalOnProperty(name="app.outbox.publisher-enabled",havingValue="true",matchIfMissing=true)public class OutboxPublisher{private static final Logger log=LoggerFactory.getLogger(OutboxPublisher.class);private final OutboxJdbcRepository repository;private final RabbitTemplate rabbit;private final AppProperties properties;private final MeterRegistry metrics;private final String worker=UUID.randomUUID().toString();public OutboxPublisher(OutboxJdbcRepository r,RabbitTemplate rabbit,AppProperties p,MeterRegistry m){repository=r;this.rabbit=rabbit;properties=p;metrics=m;}@Scheduled(fixedDelayString="${app.outbox.poll-delay:500ms}")public void poll(){repository.claim(worker,properties.outbox().batchSize(),properties.outbox().lease()).forEach(this::publish);}private void publish(OutboxJdbcRepository.ClaimedEvent e){try{MessageProperties mp=new MessageProperties();mp.setContentType(MessageProperties.CONTENT_TYPE_TEXT_PLAIN);mp.setContentEncoding(StandardCharsets.UTF_8.name());mp.setMessageId(e.eventId().toString());mp.setHeader("eventType",e.eventType());Message message=new Message(e.payload().getBytes(StandardCharsets.UTF_8),mp);CorrelationData correlation=new CorrelationData(e.eventId().toString());rabbit.send(RabbitTopology.EVENTS,e.eventType(),message,correlation);CorrelationData.Confirm confirm=correlation.getFuture().get(properties.outbox().publishTimeout().toMillis(),TimeUnit.MILLISECONDS);if(!confirm.isAck())throw new IllegalStateException("broker nack: "+confirm.getReason());repository.published(e.eventId());metrics.counter("commerce.outbox.published").increment();}catch(Exception ex){log.warn("event=outbox_publish_failed eventId={} attempt={} reason={}",e.eventId(),e.attemptCount(),ex.toString());repository.failed(e.eventId(),e.attemptCount(),ex.toString());metrics.counter("commerce.outbox.failed").increment();}}}
